/* ---- car bus: Haltech V2.35.0 subset, big-endian 16-bit fields ---- */
static inline float cluster_haltech_engine_rpm(const uint8_t d[8]) {
    uint16_t r = (uint16_t)(((uint16_t)d[CAN_HALTECHENGINE_RPM_BYTE] << 8) | d[CAN_HALTECHENGINE_RPM_BYTE + 1u]);
    return (float)r * CAN_HALTECHENGINE_RPM_FACTOR + CAN_HALTECHENGINE_RPM_OFFSET;
}
